function cleanEvent(ev) {
    if (!ev) return;
    while (ev.groupTracks.length > 0) {
        studio.project.deleteObject(ev.groupTracks[0]);
    }
    while (ev.timeline.modules.length > 0) {
        studio.project.deleteObject(ev.timeline.modules[0]);
    }
}

